import bpy, types, json
ns=bpy.app.driver_namespace['reference_authoring']
removed=0
for o in list(bpy.data.objects):
    if o.name not in ['Shore_ContinuousGround','Ocean_Surface']:
        bpy.data.objects.remove(o,do_unlink=True);removed+=1
for c in list(bpy.data.collections):
    if c.name=='Reference_Coast':bpy.data.collections.remove(c)
for name,f in list(ns.items()):
    if isinstance(f,types.FunctionType) and f.__module__ is None:
        ns[name]=types.FunctionType(f.__code__,ns,f.__name__,f.__defaults__,f.__closure__)
# Rebind every authored Python function to the shared MCP-only namespace.
for name in ['collection','srgb','material','mesh','box','tube','beam','smooth','shore','height','barrel','crate','coil','dock','roof','hut']:
    f=ns[name];ns[name]=types.FunctionType(f.__code__,ns,f.__name__,f.__defaults__,f.__closure__)
path=ns['ROOT']/'source/reference_02_structures.mcp.json'
exec(json.loads(path.read_text(encoding='utf-8'))['code'],{'bpy':bpy})
print('REPAIRED',removed,'temporary untransformed components; collections',[(c.name,len(c.objects)) for c in bpy.data.collections])
